import sqlite3
conn = sqlite3.connect('/root/data/eventlogs.db')
curr = conn.cursor()

# Get all events from WS-06 between 00:00:40 and 00:01:20
curr.execute("""SELECT event_id, timestamp, event_code, channel, provider, image, parent_image, command_line, service_name, service_file_name, target_image, target_object, src_ip, dst_ip, dst_port, details, message 
FROM events 
WHERE host = 'WS-06.corp.example' AND timestamp BETWEEN '2026-05-06T00:00:40Z' AND '2026-05-06T00:01:20Z'
ORDER BY timestamp""")

rows = curr.fetchall()
print(f"Total events on WS-06 in window: {len(rows)}")

for r in rows:
    ev_id, ts, code, chan, prov, img, pimg, cmd, s_name, s_file, t_img, t_obj, src, dst, port, det, msg = r
    # Summarize
    desc = ""
    if code == 1 or code == 4688:
        desc = f"PROCESS START: img={img} pimg={pimg} cmd={cmd}"
    elif code in (7045, 4697, 7009, 7036):
        desc = f"SERVICE: s_name={s_name} s_file={s_file} msg={msg}"
    elif code == 3:
        desc = f"NET: src={src} dst={dst}:{port}"
    elif code == 11:
        desc = f"FILE CREATE: img={img} target={t_obj or det or msg[:50]}"
    elif code == 12 or code == 13 or code == 14:
        desc = f"REGISTRY: code={code} img={img} obj={t_obj} det={det}"
    elif code == 22:
        desc = f"DNS QUERY: img={img} msg={msg[:100]}"
    elif code == 4104:
        desc = f"POWERSHELL BLOCK: msg={msg[:200]}"
    elif code == 4103:
        desc = f"POWERSHELL PIPELINE: msg={msg[:100]}"
    elif code == 10:
        # ProcessAccess - can be noisy, let's only print if it accesses something interesting like lsass or similar, or just skip if too many
        if "lsass" in (t_img or "").lower():
            desc = f"PROCESS ACCESS LSASS: img={img} target={t_img}"
        else:
            continue
    else:
        desc = f"OTHER code={code} chan={chan} msg={msg[:100] if msg else ''}"

    print(f"{ev_id} | {ts} | {code} | {desc}")

EOF
python3 parse_ws06.py > summary.txt
cat summary.txt

